public FraudResult check(Order order) throws IOException {
    try (CloseableHttpClient client = HttpClients.createDefault()) {   // client mới mỗi lần gọi
        HttpPost post = new HttpPost("http://fraud-service:8080/v1/checks");
        post.setEntity(new StringEntity(json.write(order), ContentType.APPLICATION_JSON));
        return client.execute(post, response -> json.read(response.getEntity(), FraudResult.class));
    }   // close() đóng luôn kết nối vừa dùng: order-service là bên đóng trước
}

